/// Options for streaming responses.
pub const StreamOptions = struct {
    /// If true, include token usage in the final stream chunk.
    include_usage: ?bool,
};

/// A streaming tool call being built incrementally.
pub const StreamToolCall = struct {
    /// Index of this tool call in the tool_calls array.
    index: u32,
    /// Tool call ID (typically in the first chunk for this call).
    id: ?[]const u8,
    /// Tool type (typically "function").
    call_type: ?ToolType,
    /// Partial function name and arguments.
    function: ?StreamFunctionCall,
};

/// System message guiding model behavior for the entire conversation.
pub const SystemMessage = struct {
    /// Instructions or context that apply throughout the conversation.
    ///
    /// Accepts either a plain text string or an array of content parts,
    /// mirroring `UserContent` so that `Message.system_with_parts` works.
    content: UserContent,
    /// Optional name for the system message source.
    name: ?[]const u8,
};

/// A tool call the model wants to execute.
pub const ToolCall = struct {
    /// Unique ID for this call, used to reference in tool result messages.
    id: []const u8,
    /// Tool type (always "function").
    call_type: ToolType,
    /// Function name and arguments.
    function: FunctionCall,
};

/// Tool execution result returned to the model.
pub const ToolMessage = struct {
    /// Result of the tool execution as plain text or an array of content parts
    /// (text, images, documents, audio), mirroring `UserMessage.content`.
    ///
    /// `#[serde(untagged)]` on `UserContent` means a bare JSON string still
    /// deserialises into `Text`, so tool results persisted before this field
    /// carried structured content continue to round-trip.
    content: UserContent,
    /// ID of the tool call this result responds to.
    tool_call_id: []const u8,
    /// Optional tool/function name.
    name: ?[]const u8,
};

/// Response from a transcription request.
pub const TranscriptionResponse = struct {
    /// The transcribed text.
    text: []const u8,
    /// Detected language (ISO-639-1 code).
    language: ?[]const u8,
    /// Total audio duration in seconds.
    duration: ?f64,
    /// Detailed segment-level transcription (if response_format is "verbose_json").
    segments: ?[]const TranscriptionSegment,
};

/// A segment of transcribed audio with timing information.
pub const TranscriptionSegment = struct {
    /// Segment index (0-based).
    id: u32,
    /// Start time in seconds.
    start: f64,
    /// End time in seconds.
    end: f64,
    /// Transcribed text for this segment.
    text: []const u8,
};

/// Token-usage accounting returned by the provider on each completion / embedding call.
pub const Usage = struct {
    /// Prompt tokens used. Defaults to 0 when absent (some providers omit this).
    prompt_tokens: u64,
    /// Completion tokens used. Defaults to 0 when absent (e.g. embedding responses).
    completion_tokens: u64,
    /// Total tokens used. Defaults to 0 when absent (some providers omit this).
    total_tokens: u64,
    /// Breakdown of tokens used in the prompt, including cached tokens served
    /// at the provider's discounted cache-read rate. Absent when the provider
    /// does not return prompt-token details.
    prompt_tokens_details: ?PromptTokensDetails,
    /// Breakdown of tokens used in the completion, including reasoning tokens.
    /// Absent when the provider does not return completion-token details.
    completion_tokens_details: ?CompletionTokensDetails,
};

/// User message in the conversation.
pub const UserMessage = struct {
    /// Message content as plain text or array of content parts (text, images, documents, audio).
    content: UserContent,
    /// Optional name for the user.
    name: ?[]const u8,
};

/// Configuration for polling a batch until terminal status.
///
/// All time values are in seconds as `f64` so the struct bridges across FFI
/// boundaries without requiring a `Duration` shim.
pub const WaitForBatchConfig = struct {
    /// Initial interval between polls, in seconds.
    initial_interval_secs: f64,
    /// Maximum interval between polls (backoff plateau), in seconds.
    max_interval_secs: f64,
    /// Exponential backoff multiplier (e.g., 1.5 increases delay by 50% each poll).
    backoff_multiplier: f32,
    /// Optional timeout in seconds — polling fails if this duration is exceeded.
    timeout_secs: ?f64,
};

/// Content shape for assistant messages.
///
/// `#[serde(untagged)]` means providers returning a plain scalar string for the
/// `content` field still deserialise correctly into `AssistantContent.Text(_)`.
/// Providers returning an array of typed parts (e.g. after an image-generation
/// or audio-synthesis request) deserialise into `AssistantContent.Parts(_)`.
pub const AssistantContent = union(enum) {
    /// Plain text response (the common case for text-only models).
    text: []const u8,
    /// Structured parts — text, refusals, output images, output audio.
    parts: []const AssistantPart,
};

/// One part of a structured assistant response.
///
/// `#[serde(tag = "type", rename_all = "snake_case")]` matches OpenAI's
/// parts-spec discriminator (`"type": "text"`, `"type": "output_image"`, …).
pub const AssistantPart = union(enum) {
    /// A text segment of the response.
    text: []const u8,
    /// A refusal — the model declined to respond.
    refusal: []const u8,
    /// An image produced by the model (e.g. `gpt-image-1`, Gemini Imagen).
    output_image: ImageUrl,
    /// Audio produced by the model (e.g. `gpt-4o-audio-preview`).
    output_audio: AudioContent,
};

/// How the API key is sent in the HTTP request.
pub const AuthHeaderFormat = union(enum) {
    /// Bearer token: `Authorization: Bearer <key>`
    bearer: void,
    /// Custom header: e.g., `X-Api-Key: <key>`
    api_key: []const u8,
    /// No authentication required.
    none: void,
};

/// Auth scheme used by a provider.
pub const AuthType = enum {
    /// Standard `Authorization: Bearer <key>` header.
    bearer,
    /// `x-api-key: <key>` header (also handles `"header"` and `"x-api-key"` aliases).
    api_key,
    /// No authentication header required.
    none,
    /// Unrecognised auth scheme — falls back to bearer.
    unknown,
};

/// Status of a batch job.
pub const BatchStatus = enum {
    /// Validating the input file.
    validating,
    /// Job failed.
    failed,
    /// Job is running.
    in_progress,
    /// Finalizing results.
    finalizing,
    /// Job completed successfully.
    completed,
    /// Job expired before completion.
    expired,
    /// Job is being cancelled.
    cancelling,
    /// Job has been cancelled.
    cancelled,
};

/// Storage backend for the response cache.
pub const CacheBackend = union(enum) {
    /// In-memory LRU cache (default). No external dependencies.
    memory: void,
    /// OpenDAL-backed storage. Supports 40+ backends (S3, Redis, GCS, local FS, etc.).
    open_dal: struct {
        scheme: []const u8,
        config: std.StringHashMap([]const u8),
    },
};

/// Observable state of a circuit breaker.
pub const CircuitState = enum {
    /// Requests flow through normally.
    closed,
    /// All requests are rejected; the circuit is waiting for the backoff to elapse.
    open,
    /// One probe request is allowed through to test service health.
    half_open,
};

/// A single content part in a user message — text, image, document, or audio.
pub const ContentPart = union(enum) {
    /// Plain text.
    text: []const u8,
    /// Image identified by URL (with optional detail level).
    image_url: ImageUrl,
    /// Document file (PDF, CSV, etc.) as base64 or URL.
    document: DocumentContent,
    /// Audio input as base64.
    input_audio: AudioContent,
