/// The format in which the embedding vectors are returned.
pub const EmbeddingFormat = enum {
    /// 32-bit floating-point numbers (default).
    float,
    /// Base64-encoded string representation of the floats.
    base64,
};

/// Text, texts, or multimodal content to embed.
pub const EmbeddingInput = union(enum) {
    /// Single text string.
    single: []const u8,
    /// Multiple text strings (batch embedding).
    multiple: []const []const u8,
    /// Text and image parts for a single multimodal embedding.
    multimodal: []const EmbeddingContentPart,
};

/// How budget limits are enforced.
pub const Enforcement = enum {
    /// Reject requests that would exceed the budget with
    /// `LiterLlmError.BudgetExceeded`.
    hard,
    /// Allow requests through but emit a `tracing.warn!` when the budget is
