/// A document to be reranked — either a plain string or an object with a text field.
pub const RerankDocument = union(enum) {
    /// Plain text document content.
    text: []const u8,
    /// Document with explicit text field (may include metadata).
    object: []const u8,
};

/// Wire format for the chat completions `response_format` field.
///
/// # Provider mapping
///
/// - **OpenAI** (and OpenAI-compatible providers): emitted verbatim as
///   `{"type": "json_schema", "json_schema": {...}}` per the
///   chat-completions spec.
///
/// - **Gemini / Vertex AI**: translated to
///   `generationConfig.responseMimeType = "application/json"` and
///   `generationConfig.responseSchema = <schema>`. The `name`,
///   `description`, and `strict` fields are dropped — Gemini's
///   structured-output API does not consume them.
///
/// - **Anthropic**: no native JSON mode. A system instruction is
///   prepended asking the model to respond with valid JSON.
///   `strict` is advisory only; callers should still validate the
///   returned JSON if the schema is load-bearing.
pub const ResponseFormat = union(enum) {
    /// Plain text output (default).
    text: void,
    /// Output must be valid JSON object (no schema validation).
    json_object: void,
    /// Output must conform to the specified JSON schema.
    json_schema: JsonSchemaFormat,
};

/// Stop sequence(s) that cause the model to stop generating.
pub const StopSequence = union(enum) {
    /// Single stop sequence.
    single: []const u8,
    /// Multiple stop sequences.
    multiple: []const []const u8,
};

/// The streaming wire format a provider uses for its response stream.
///
/// Most providers use standard Server-Sent Events (SSE). AWS Bedrock uses
/// a proprietary binary EventStream framing.
///
/// Deserialized from the `streaming_format` JSON field via `serde`.
pub const StreamFormat = enum {
    /// Standard Server-Sent Events (text/event-stream).
    sse,
    /// AWS EventStream binary framing (application/vnd.amazon.eventstream).
    aws_event_stream,
};

/// Tool usage mode or a specific tool to call.
pub const ToolChoice = union(enum) {
    /// Predefined mode: auto, required, or none.
    mode: ToolChoiceMode,
    /// Force a specific tool to be called.
    specific: SpecificToolChoice,
};

/// Tool choice mode.
pub const ToolChoiceMode = enum {
    /// Model may or may not call tools; default behavior.
    auto,
    /// Model must call at least one tool.
    required,
    /// Model must not call any tools.
    none,
};

/// The type discriminator for tool/tool-call objects.
///
/// Per the OpenAI spec this is always `"function"`. Using an enum enforces
/// that constraint at the type level and rejects any other value on
/// deserialization.
pub const ToolType = enum {
    function,
};

/// User message content as either plain text or a list of multimodal parts.
pub const UserContent = union(enum) {
    /// Plain text content.
    text: []const u8,
    /// Array of content parts (text, images, documents, audio).
    parts: []const ContentPart,
};

/// Return all provider configs from the registry.
///
/// Useful for tooling, documentation generation, or runtime enumeration.
/// Returns the public `ProviderConfig` slice (without capability flags).
/// To query capability flags for a specific provider use `capabilities`.
pub fn all_providers() LiterLlmError![]u8 {
    const _result = c.literllm_all_providers();
    if (c.literllm_last_error_code() != 0) {
        return _error_with_message(LiterLlmError);
    }
    if (_result == null) {
        return _error_with_message(LiterLlmError);
    }
    const _result_len = c.literllm_all_providers_len();
    return blk: {
        if (_result == null) return error.UnknownFfiError;
        const slice = _result[0.._result_len];
        defer _free_string(_result);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    };
}

/// Return the capability flags for a named provider.
///
/// Performs an O(n) linear scan over the embedded registry (174 entries).
/// Returns an owned value so bindings can pass capability data without
/// borrowing registry internals.
///
/// For unknown `provider_name` values the function returns an all-`false`
/// sentinel so callers never need to handle `Option`.
pub fn capabilities(provider_name: []const u8) error{OutOfMemory}![]u8 {
    const provider_name_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{provider_name}, 0);
    defer std.heap.c_allocator.free(provider_name_z);
    const _result = c.literllm_capabilities(provider_name_z);
    return blk: {
        if (_result == 0) return error.OutOfMemory;
        const value = _result;
        defer c.literllm_provider_capabilities_free(value);
        const _json_ptr = c.literllm_provider_capabilities_to_json(value);
        if (_json_ptr == null) return error.OutOfMemory;
        defer _free_string(_json_ptr);
        const slice = std.mem.sliceTo(_json_ptr, 0);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    };
}

/// Return provenance for the active runtime or embedded model catalog.
pub fn catalog_info() error{OutOfMemory}!?[]u8 {
    const _result = c.literllm_catalog_info();
    return if (_result == 0) null else blk: {
        if (_result == 0) return error.OutOfMemory;
        const value = _result;
        defer c.literllm_catalog_info_free(value);
        const _json_ptr = c.literllm_catalog_info_to_json(value);
        if (_json_ptr == null) return error.OutOfMemory;
        defer _free_string(_json_ptr);
        const slice = std.mem.sliceTo(_json_ptr, 0);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    };
}

/// Assert that `current_len + incoming` does not exceed `limit`.
///
/// Call this before appending `incoming` bytes to any buffer that must
/// stay below `limit`. Returns `Err(LiterLlmError.Streaming)` on overflow
/// and emits a `tracing.warn!` with context.
pub fn check_bound(context: []const u8, current_len: u64, incoming: u64, limit: u64) LiterLlmError!void {
    const context_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{context}, 0);
    defer std.heap.c_allocator.free(context_z);
    _ = c.literllm_check_bound(context_z, current_len, incoming, limit);
    if (c.literllm_last_error_code() != 0) {
        return _error_with_message(LiterLlmError);
    }
    return;
}

/// Remove all guardrails from the global registry.
///
/// Primarily useful in tests to reset state between test cases.
///
/// If the lock was poisoned by a panicking guardrail on a previous access,
/// the poisoned state is recovered rather than propagating the panic.
pub fn clear() void {
    _ = c.literllm_clear();
}

/// Clear the overlay registry, reverting `completion_cost`,
/// `completion_cost_with_cache`, and `model_info` to the
/// embedded catalog.
///
/// Primarily a test seam (see `install_catalog_overlay_from_str`); also
/// usable by long-running processes that want to abandon a runtime refresh.
pub fn clear_catalog_overlay() void {
    _ = c.literllm_clear_catalog_overlay();
}

/// Calculate the estimated cost of a completion given a model name and token
/// counts.
///
/// Returns `null` if the model is not present in the embedded pricing registry.
/// Returns `Some(cost_usd)` otherwise, where the value is in US dollars.
///
/// When an exact model name match is not found, progressively shorter prefixes
/// are tried by stripping from the last `-` or `.` separator. For example,
/// `gpt-4-0613` will match `gpt-4` if no `gpt-4-0613` entry exists.
pub fn completion_cost(model: []const u8, prompt_tokens: u64, completion_tokens: u64) error{OutOfMemory}!?f64 {
    const model_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{model}, 0);
    defer std.heap.c_allocator.free(model_z);
    if (c.literllm_completion_cost_has_result(model_z, prompt_tokens, completion_tokens) != 1) {
        return null;
    }
    const _result = c.literllm_completion_cost(model_z, prompt_tokens, completion_tokens);
    return _result;
}

/// Calculate the estimated cost of a completion, accounting for cached
/// (cache-hit) prompt tokens billed at the provider's discounted rate.
///
/// `cached_tokens` is the count of prompt tokens served from the provider's
/// prompt cache. It must be `<= prompt_tokens` (cached tokens are a subset of
/// the prompt). The non-cached portion is billed at `input_cost_per_token`
/// and the cached portion at `cache_read_input_token_cost` when the model
/// has cache pricing; otherwise the entire prompt is billed at the regular
/// input rate.
///
/// Returns `null` if the model is not present in the embedded pricing
/// registry, mirroring `completion_cost`.
///
/// When the model has `ModelPricing.tiers`, the tier whose
/// `min_context_tokens` is the highest value `<= prompt_tokens` supplies the
/// input/output/cache rates for the whole call; models without tiers (or
/// when `prompt_tokens` is below every tier threshold) use the base rates
/// unchanged, matching the original flat-rate behaviour.
pub fn completion_cost_with_cache(model: []const u8, prompt_tokens: u64, cached_tokens: u64, completion_tokens: u64) error{OutOfMemory}!?f64 {
    const model_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{model}, 0);
    defer std.heap.c_allocator.free(model_z);
    if (c.literllm_completion_cost_with_cache_has_result(model_z, prompt_tokens, cached_tokens, completion_tokens) != 1) {
        return null;
    }
    const _result = c.literllm_completion_cost_with_cache(model_z, prompt_tokens, cached_tokens, completion_tokens);
    return _result;
}

/// Calculate completion cost including both prompt-cache reads and writes.
pub fn completion_cost_with_cache_details(model: []const u8, prompt_tokens: u64, cached_tokens: u64, cache_creation_tokens: u64, completion_tokens: u64) error{OutOfMemory}!?f64 {
    const model_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{model}, 0);
    defer std.heap.c_allocator.free(model_z);
    if (c.literllm_completion_cost_with_cache_details_has_result(model_z, prompt_tokens, cached_tokens, cache_creation_tokens, completion_tokens) != 1) {
        return null;
    }
    const _result = c.literllm_completion_cost_with_cache_details(model_z, prompt_tokens, cached_tokens, cache_creation_tokens, completion_tokens);
    return _result;
}

/// Return the set of complex provider names.
///
/// Complex providers require custom auth/routing logic beyond simple bearer
/// tokens (e.g. AWS Bedrock SigV4, Vertex AI OAuth2).
///
/// The returned reference points into the static registry — no allocation.
pub fn complex_provider_names() LiterLlmError![]u8 {
    const _result = c.literllm_complex_provider_names();
    if (c.literllm_last_error_code() != 0) {
        return _error_with_message(LiterLlmError);
    }
    if (_result == null) {
        return _error_with_message(LiterLlmError);
    }
    const _result_len = c.literllm_complex_provider_names_len();
    return blk: {
        if (_result == null) return error.UnknownFfiError;
        const slice = _result[0.._result_len];
        defer _free_string(_result);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    };
}

/// Count tokens for a full `ChatCompletionRequest`.
///
/// Sums tokens across all message text contents plus a per-message overhead
/// of ~4 tokens (for role, separators, and formatting metadata). Tool
/// definitions and multimodal content parts (images, audio, documents) are
/// not counted — only textual content contributes to the token total.
///
/// **Errors:**
///
/// Returns `LiterLlmError.BadRequest` if the tokenizer cannot be loaded or
/// if tokenization fails for any message.
pub fn count_request_tokens(model: []const u8, req: []const u8) LiterLlmError!u64 {
    const model_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{model}, 0);
    defer std.heap.c_allocator.free(model_z);
    const req_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{req}, 0);
    defer std.heap.c_allocator.free(req_z);
    const req_handle = c.literllm_chat_completion_request_from_json(req_z);
    if (req_handle == 0) return _error_with_message(LiterLlmError);
    defer c.literllm_chat_completion_request_free(req_handle);
    const _result = c.literllm_count_request_tokens(model_z, req_handle);
    if (c.literllm_last_error_code() != 0) {
        return _error_with_message(LiterLlmError);
    }
    return _result;
}

/// Count tokens in a text string using the tokenizer for the given model.
///
/// The tokenizer is resolved from the model name prefix (e.g. `"gpt-4o"` maps
/// to the `Xenova/gpt-4o` HuggingFace tokenizer). Tokenizers are cached after
/// first load.
///
/// **Errors:**
///
/// Returns `LiterLlmError.BadRequest` if the tokenizer cannot be loaded
/// (e.g. network failure on first use) or if tokenization itself fails.
pub fn count_tokens(model: []const u8, text: []const u8) LiterLlmError!u64 {
    const model_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{model}, 0);
    defer std.heap.c_allocator.free(model_z);
    const text_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{text}, 0);
    defer std.heap.c_allocator.free(text_z);
    const _result = c.literllm_count_tokens(model_z, text_z);
    if (c.literllm_last_error_code() != 0) {
        return _error_with_message(LiterLlmError);
    }
    return _result;
}

/// Create a new LLM client with simple scalar configuration.
///
/// This is the primary binding entry-point. All parameters except `api_key`
/// are optional — omitting them uses the same defaults as
/// `ClientConfigBuilder`.
///
/// **Errors:**
///
/// Returns `LiterLlmError` if the underlying HTTP client cannot be
/// constructed, or if the resolved provider configuration is invalid.
pub fn create_client(api_key: []const u8, base_url: ?[]const u8, timeout_secs: ?u64, max_retries: ?u32, model_hint: ?[]const u8) LiterLlmError!DefaultClient {
    const api_key_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{api_key}, 0);
    defer std.heap.c_allocator.free(api_key_z);
    const base_url_z: ?[:0]u8 = if (base_url) |v| try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{v}, 0) else null;
    defer if (base_url_z) |z| std.heap.c_allocator.free(z);
    const model_hint_z: ?[:0]u8 = if (model_hint) |v| try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{v}, 0) else null;
    defer if (model_hint_z) |z| std.heap.c_allocator.free(z);
    const _result = c.literllm_create_client(api_key_z, if (base_url_z) |z| z.ptr else null, if (timeout_secs) |v| v else std.math.maxInt(u64), if (max_retries) |v| v else std.math.maxInt(u32), if (model_hint_z) |z| z.ptr else null);
    if (c.literllm_last_error_code() != 0) {
        return _error_with_message(LiterLlmError);
    }
    return blk: {
        if (_result == 0) return error.UnknownFfiError;
        break :blk DefaultClient{ ._handle = _result };
    };
}

/// Create a new LLM client from a JSON string.
///
/// The JSON object accepts the same fields as `liter-llm.toml` (snake_case).
/// Middleware keys (`cache`, `budget`, `cooldown_secs`, `rate_limit`,
/// `in_flight_limit`, `health_check_secs`, `cost_tracking`, `tracing`) are
/// applied: the returned client routes the `LlmClient` methods (`chat`,
/// `chat_stream`, `embed`, `list_models`, `image_generate`, `speech`,
/// `transcribe`, `moderate`, `rerank`, `search`, `ocr`) through the managed
/// Tower stack. File, batch and response operations bypass it. Each `providers`
/// entry is registered process-wide via `register_custom_provider`.
///
/// **Errors:**
///
/// Returns `LiterLlmError.BadRequest` if `json` is not valid JSON, contains
/// unknown fields, or sets middleware keys in a build without the `tower` and
/// `native-http` features. Provider registration failures are propagated.
pub fn create_client_from_json(json: []const u8) LiterLlmError!DefaultClient {
    const json_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{json}, 0);
    defer std.heap.c_allocator.free(json_z);
    const _result = c.literllm_create_client_from_json(json_z);
    if (c.literllm_last_error_code() != 0) {
        return _error_with_message(LiterLlmError);
    }
    return blk: {
        if (_result == 0) return error.UnknownFfiError;
        break :blk DefaultClient{ ._handle = _result };
    };
}

/// Decode a base64 data URL into `DecodedDataUrl`.
///
/// Returns `null` for:
///
/// - Non-data URLs (strings that do not start with `"data:"`).
/// - Malformed prefixes (missing `";base64,"` marker).
/// - Invalid base64 payloads.
///
/// The returned MIME string is extracted verbatim from the URL prefix —
/// it is not validated or normalised.
pub fn decode_data_url(url: []const u8) error{OutOfMemory}!?[]u8 {
    const url_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{url}, 0);
    defer std.heap.c_allocator.free(url_z);
    const _result = c.literllm_decode_data_url(url_z);
    return if (_result == 0) null else blk: {
        if (_result == 0) return error.OutOfMemory;
        const value = _result;
        defer c.literllm_decoded_data_url_free(value);
        const _json_ptr = c.literllm_decoded_data_url_to_json(value);
        if (_json_ptr == null) return error.OutOfMemory;
        defer _free_string(_json_ptr);
        const slice = std.mem.sliceTo(_json_ptr, 0);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    };
}

/// Encode bytes as a base64 data URL: `data:<mime>;base64,<b64>`.
///
/// `mime` defaults to `IMAGE_PNG` when `null`.
pub fn encode_data_url(bytes: []const u8, mime: ?[]const u8) error{OutOfMemory}![]u8 {
    const mime_z: ?[:0]u8 = if (mime) |v| try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{v}, 0) else null;
    defer if (mime_z) |z| std.heap.c_allocator.free(z);
    const _result = c.literllm_encode_data_url(bytes.ptr, bytes.len, if (mime_z) |z| z.ptr else null);
    const _result_len = c.literllm_encode_data_url_len(bytes.ptr, bytes.len, if (mime_z) |z| z.ptr else null);
    return blk: {
        const slice = _result[0.._result_len];
        defer _free_string(_result);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    };
}

/// Install the `ring` crypto provider as the rustls process default, idempotently.
///
/// rustls 0.23+ removed the implicit default provider. This function installs
/// `ring` once per process. Subsequent calls are no-ops. Calling it after
/// another rustls crypto provider has already been installed is safe: the
/// `Err` from `install_default()` is silently ignored.
///
/// Called automatically by every internal `reqwest.Client` constructor
/// (auth providers, default HTTP client). Bindings and downstream consumers
/// reach those constructors transitively, so no manual init is required.
///
/// WASM builds are exempt — the WASM target uses the browser/Node.js fetch
/// API instead of rustls, so no crypto provider is needed.
///
/// Windows builds use native-tls (SChannel) via reqwest, so rustls is not
/// present and no crypto provider installation is needed.
pub fn ensure_crypto_provider() void {
    _ = c.literllm_ensure_crypto_provider();
}

