    return _result != 0;
}

/// Iterator over `ChatCompletionChunk` items in a streaming response.
pub const ChatCompletionChunkStream = struct {
    _handle: u64,

    /// Fetch the next item from the stream, or null at end-of-stream.
    /// Returns an error on mid-stream failure; null on clean EOS.
    pub fn next(self: *ChatCompletionChunkStream) (LiterLlmError || error{ OutOfMemory, HandleClosed })!?ChatCompletionChunk {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _chunk = c.literllm_default_client_chat_stream_next(handle);
        if (_chunk == 0) {
            // Check errno: 0 = clean EOS, != 0 = error
            const _code = c.literllm_last_error_code();
            if (_code == 5) return error.Cancelled;
            if (_code != 0) return error.UnknownFfiError;
            return null;
        }
        defer c.literllm_chat_completion_chunk_free(_chunk);
        const _json = c.literllm_chat_completion_chunk_to_json(_chunk);
        if (_json == null) return _error_with_message(LiterLlmError);
        defer c.literllm_free_string(_json);
        const _json_slice = std.mem.span(_json);
        return try std.json.parseFromSliceLeaky(ChatCompletionChunk, std.heap.c_allocator, _json_slice, .{ .ignore_unknown_fields = true, .allocate = .alloc_always });
    }

    /// Release the underlying stream handle.
    pub fn deinit(self: *ChatCompletionChunkStream) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.literllm_default_client_chat_stream_free(handle);
    }
};

/// Default client implementation backed by `reqwest`.
///
/// Sends requests to 174 LLM providers with automatic provider detection
/// and per-request routing. The provider is resolved at construction time
/// from `model_hint` (or defaults to OpenAI), but individual requests can
/// override the provider via model name prefix (e.g. `"anthropic/claude-3-5-sonnet"`
/// routes to Anthropic regardless of construction-time setting).
///
/// When the model prefix does not match any known provider, the construction-time
/// provider is used as the fallback. This enables seamless migration between
/// providers by changing only the model name.
///
/// The provider is stored behind an `Arc` so it can be shared cheaply into
/// async closures and streaming tasks. Pre-computed auth headers and extra
/// headers are cached at construction to avoid redundant encoding on every request.
pub const DefaultClient = struct {
    _handle: u64,

    pub fn chat(self: *DefaultClient, req: []const u8) (LiterLlmError || error{ OutOfMemory, HandleClosed })![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const req_z = try std.heap.c_allocator.dupeZ(u8, req);
        defer std.heap.c_allocator.free(req_z);
        const req_handle = c.literllm_chat_completion_request_from_json(req_z.ptr);
        if (req_handle == 0) return error.UnknownFfiError;
        defer c.literllm_chat_completion_request_free(req_handle);
        const _result = c.literllm_default_client_chat(handle, req_handle);
        if (c.literllm_last_error_code() != 0) {
            return _error_with_message(LiterLlmError);
        }
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            const value = _result;
            defer c.literllm_chat_completion_response_free(value);
            const _json_ptr = c.literllm_chat_completion_response_to_json(value) orelse return error.OutOfMemory;
            defer c.literllm_free_string(_json_ptr);
            const _json_slice = std.mem.span(_json_ptr);
            const owned = try std.heap.c_allocator.dupe(u8, _json_slice);
            break :blk owned;
        };
    }

    pub fn chat_stream(self: *DefaultClient, req: []const u8) (LiterLlmError || error{ OutOfMemory, HandleClosed })!ChatCompletionChunkStream {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const req_z = try std.heap.c_allocator.dupeZ(u8, req);
        const req_handle = c.literllm_chat_completion_request_from_json(req_z.ptr);
        std.heap.c_allocator.free(req_z);
        if (req_handle == 0) {
            return error.UnknownFfiError;
        }
        defer c.literllm_chat_completion_request_free(req_handle);
        const _stream_handle = c.literllm_default_client_chat_stream_start(handle, req_handle);
        if (_stream_handle == 0) {
            return error.UnknownFfiError;
        }
        return ChatCompletionChunkStream{ ._handle = _stream_handle };
    }

    pub fn embed(self: *DefaultClient, req: []const u8) (LiterLlmError || error{ OutOfMemory, HandleClosed })![]u8 {
        const handle = self._handle;
